import logging
import os
import re
import shutil
import subprocess
import uuid
from pathlib import Path

import typer

from eva.security.sensitive_files import is_sensitive_file
from eva.ui.formatter import print_error, print_info

logger = logging.getLogger(__name__)


def _is_within_root(path: Path, root: Path) -> bool:
    try:
        path.resolve().relative_to(root.resolve())
        return True
    except (ValueError, RuntimeError):
        return False


def _fix_diff_headers(diff_text: str) -> str:
    """Fixes malformed hunk headers (e.g., bare '@@') generated by LLMs."""
    lines = diff_text.strip().splitlines()
    fixed_lines = []
    target_content = []

    i = 0
    while i < len(lines):
        line = lines[i]
        if line.startswith(("--- ", "+++ ")):
            current_file = line[4:].strip()
            if current_file.startswith(("a/", "b/")):
                current_file = current_file[2:]

            fixed_lines.append(line)

            if line.startswith("+++ "):
                try:
                    p = Path(current_file)
                    if p.is_file():
                        with open(p, "r", encoding="utf-8") as f:
                            target_content = f.read().splitlines()
                    else:
                        target_content = []
                except (OSError, UnicodeDecodeError):
                    target_content = []
        elif line.strip() == "@@":
            old_lines = []
            j = i + 1
            while j < len(lines) and not lines[j].startswith("@@") and not lines[j].startswith("---"):
                if lines[j].startswith("-") or lines[j].startswith(" "):
                    old_lines.append(lines[j][1:])
                j += 1

            start_idx = 0
            if old_lines and target_content:
                for k in range(len(target_content) - len(old_lines) + 1):
                    if target_content[k : k + len(old_lines)] == old_lines:
                        start_idx = k
                        break

            start_line = start_idx + 1
            fixed_lines.append(f"@@ -{start_line},1 +{start_line},1 @@")
        else:
            fixed_lines.append(line)
        i += 1

    return "\n".join(fixed_lines) + "\n"


def extract_unified_diff(model_output: str) -> str:
    text = model_output.strip()
    fenced = re.fullmatch(r"```(?:diff|patch)?\s*\n(?P<body>.*?)\n```", text, flags=re.DOTALL)
    if fenced:
        text = fenced.group("body").strip()

    if "\n--- " not in f"\n{text}" and "\ndiff --git " not in f"\n{text}":
        raise ValueError("model did not return a unified diff")

    cleaned_lines = []
    for line in text.splitlines():
        if line.startswith(("***", "Apply", "End of File")):
            break
        cleaned_lines.append(line)

    cleaned_text = "\n".join(cleaned_lines)
    return _fix_diff_headers(cleaned_text)


def apply_diff_python_fallback(
    diff_text: str,
    authorized_paths: set[Path] | None = None,
    force_include: set[str] | None = None,
    root_dir: Path | None = None,
) -> bool:
    """Wrapper delegating to apply_unified_diff for backward compatibility."""
    return apply_unified_diff(
        diff_text,
        authorized_paths=authorized_paths,
        force_include=force_include,
        root_dir=root_dir,
    )


def apply_unified_diff(
    diff_text: str,
    authorized_paths: set[Path] | None = None,
    force_include: set[str] | None = None,
    root_dir: Path | None = None,
) -> bool:
    """Apply a unified diff with strict path containment, sensitive file checks,

    scope authorization, and atomic multi-file patching with rollback.
    """
    root = (root_dir or Path.cwd()).resolve()
    lines = diff_text.splitlines()

    files_hunks: dict[str, list[list[str]]] = {}
    current_file = None
    current_hunk: list[str] | None = None

    i = 0
    while i < len(lines):
        line = lines[i]
        if line.startswith("--- "):
            if current_hunk is not None and current_file:
                files_hunks[current_file].append(current_hunk)
                current_hunk = None
            fname = line[4:].strip().removeprefix("a/")
            current_file = fname
            if current_file not in files_hunks:
                files_hunks[current_file] = []
        elif line.startswith("+++ "):
            fname = line[4:].strip().removeprefix("b/")
            current_file = fname
            if current_file not in files_hunks:
                files_hunks[current_file] = []
        elif line.startswith("@@"):
            if current_hunk is not None and current_file:
                files_hunks[current_file].append(current_hunk)
            current_hunk = []
        elif current_hunk is not None:
            if line.startswith(("***", "Apply", "End of File")):
                break
            if line.startswith(("-", "+", " ")) or line == "":
                current_hunk.append(line)
            else:
                current_hunk.append(" " + line)
        i += 1

    if current_hunk is not None and current_file:
        files_hunks[current_file].append(current_hunk)

    if not files_hunks:
        print_error("No files found in diff.")
        return False

    # 1. Strict validation of all target files before modifying anything
    validated_targets: dict[str, Path] = {}
    for filename, hunks in files_hunks.items():
        if not filename:
            print_error("Empty filename in diff.")
            return False

        # Reject path traversal
        parts = filename.replace("\\", "/").split("/")
        if ".." in parts or filename.startswith(("../", "..\\")):
            print_error(f"Path traversal detected in diff target: {filename}")
            return False

        # Reject absolute paths
        if (
            filename.startswith(("/", "\\"))
            or (len(filename) > 1 and filename[1] == ":")
            or Path(filename).is_absolute()
        ):
            print_error(f"Absolute path rejected in diff target: {filename}")
            return False

        # Reject symlinks (target or any intermediate ancestor component up to root) BEFORE resolving
        norm_filename = filename.replace("\\", "/")
        raw_target = root / norm_filename
        curr = raw_target
        while curr != root and curr != curr.parent:
            if curr.is_symlink():
                print_error(f"Symlink rejected in diff target: {filename}")
                return False
            curr = curr.parent

        # Resolve path
        try:
            target_path = raw_target.resolve()
        except (ValueError, OSError) as exc:
            print_error(f"Failed to resolve target path '{filename}': {exc}")
            return False

        # Verify containment within repo root
        if not _is_within_root(target_path, root):
            print_error(f"Target path outside repository root: {filename}")
            return False

        # Verify regular file
        if target_path.exists() and not target_path.is_file():
            print_error(f"Target is not a regular file: {filename}")
            return False

        # Verify sensitive files
        rel_to_root = target_path.relative_to(root)
        if is_sensitive_file(rel_to_root) and (not force_include or rel_to_root.as_posix() not in force_include):
            print_error(f"Sensitive file modification blocked: {filename}")
            return False

        # Verify authorized scope
        if authorized_paths is not None:
            auth_resolved = {p.resolve() for p in authorized_paths}
            if target_path not in auth_resolved:
                print_error(f"Target path outside authorized scope: {filename}")
                return False

        # Verify target exists on disk
        if not target_path.is_file():
            print_error(f"Target file does not exist: {filename}")
            return False

        # Verify hunks non-empty and contains modifications
        if not hunks:
            print_error(f"No hunks found for target file: {filename}")
            return False

        has_mod = any(any(l.startswith(("+", "-")) for l in hunk) for hunk in hunks)
        if not has_mod:
            print_error(f"Hunk contains no changes for target file: {filename}")
            return False

        validated_targets[filename] = target_path

    # 2. Dry-run hunk application in memory for all files
    staged_updates: dict[Path, str] = {}
    for filename, target_path in validated_targets.items():
        hunks = files_hunks[filename]
        try:
            content = target_path.read_text(encoding="utf-8")
        except (OSError, UnicodeDecodeError) as exc:
            print_error(f"Failed to read target file '{target_path}': {exc}")
            return False

        file_lines = content.splitlines()

        for hunk in hunks:
            old_slice = []
            new_slice = []
            for hline in hunk:
                if hline.startswith("-"):
                    old_slice.append(hline[1:])
                elif hline.startswith("+"):
                    new_slice.append(hline[1:])
                elif hline.startswith(" "):
                    old_slice.append(hline[1:])
                    new_slice.append(hline[1:])

            if not old_slice:
                file_lines.extend(new_slice)
                continue

            match_idx = -1
            for k in range(len(file_lines) - len(old_slice) + 1):
                if file_lines[k : k + len(old_slice)] == old_slice:
                    match_idx = k
                    break

            if match_idx == -1:
                for k in range(len(file_lines) - len(old_slice) + 1):
                    if [l.strip() for l in file_lines[k : k + len(old_slice)]] == [l.strip() for l in old_slice]:
                        match_idx = k
                        break

            if match_idx == -1:
                print_error(f"Hunk could not be matched in {filename}")
                return False

            file_lines = file_lines[:match_idx] + new_slice + file_lines[match_idx + len(old_slice) :]

        updated_text = "\n".join(file_lines)
        if content.endswith("\n"):
            updated_text += "\n"

        staged_updates[target_path] = updated_text

    # 3. Atomic application with rollback
    backups: dict[Path, Path] = {}
    try:
        for target_path, new_content in staged_updates.items():
            bak_path = target_path.with_name(target_path.name + ".bak")
            shutil.copy2(target_path, bak_path)
            backups[target_path] = bak_path

            tmp_path = target_path.with_name(f".{target_path.name}.tmp.{uuid.uuid4().hex}")
            with open(tmp_path, "w", encoding="utf-8") as f:
                f.write(new_content)
                f.flush()
                os.fsync(f.fileno())
            os.replace(tmp_path, target_path)

        for target_path, bak_path in backups.items():
            print_info(f"Backup created: {bak_path} (Recovery: cp '{bak_path}' '{target_path}')")
        return True

    except (OSError, RuntimeError) as exc:
        print_error(f"Error applying patch atomically: {exc}. Rolling back...")
        for target_path, bak_path in backups.items():
            try:
                if bak_path.exists():
                    shutil.copy2(bak_path, target_path)
            except OSError as rb_exc:
                logger.debug("Failed to rollback %s: %s", target_path, rb_exc)
        return False


def run_git(args: list[str]) -> subprocess.CompletedProcess[str]:
    try:
        return subprocess.run(["git", *args], capture_output=True, text=True, check=False)
    except FileNotFoundError:
        print_error("git is not installed on this system.")
        raise typer.Exit(1)
